svg.script:
    async function startApp() {
      const root = document.getElementById("webpage-root");
      if (!root) return;

      const url = "https://githubusercontent.com";

      try {
        const res = await fetch(url);
        if (!res.ok) throw new Error("Network response failed");
        const html = await res.text();

        // Build the isolated XHTML frame context cleanly
        const frame = document.createElementNS("http://w3.org", "iframe");
        frame.style.width = "100%";
        frame.style.height = "100%";
        frame.style.border = "none";

        root.innerHTML = "";
        root.appendChild(frame);

        // Populating the frame safely via srcdoc eliminates any XML string translation bugs
        frame.srcdoc = html;

      } catch (err) {
        root.innerHTML = "
Initialization Error: " + err.message + "";
      }
    }

    // Safely hook directly into the standard animation loop for immediate engine execution
    requestAnimationFrame(startApp);
